1	"use client";
2	
3	import React from "react";
4	import { motion } from "framer-motion";
5	import { ArrowRight, PlayCircle } from "lucide-react";
6	import { BRAND, FONT, SHADOW, GRADIENT, fadeUp, stagger } from "@/lib/brand";
7	import { MangomintBlobs } from "@/components/brand/mangomint-blobs";
8	import { SectionEyebrow } from "@/components/shared/section-eyebrow";
9	import type { AccentKey } from "@/lib/brand";
10	
11	interface HeroSectionProps {
12	  eyebrow: string;
13	  eyebrowAccent?: AccentKey;
14	  headline: string;
15	  italicWord?: string;
16	  subhead: string;
17	  primaryCTA: { label: string; href: string };
18	  secondaryCTA?: { label: string; href: string; icon?: "play" };
19	  trustStats?: Array<{ stat: string; label: string }>;
20	  variant?: "default" | "centered" | "dark";
21	  showBlobs?: boolean;
22	}
23	
24	export function HeroSection({
25	  eyebrow,
26	  eyebrowAccent = "rust",
27	  headline,
28	  italicWord,
29	  subhead,
30	  primaryCTA,
31	  secondaryCTA,
32	  trustStats,
33	  variant = "default",
34	  showBlobs = true,
35	}: HeroSectionProps) {
36	  const isDark = variant === "dark";
37	  const isCentered = variant === "centered" || isDark;
38	
39	  function renderHeadline() {
40	    if (!italicWord || !headline.includes(italicWord)) {
41	      return headline;
42	    }
43	    const parts = headline.split(italicWord);
44	    return (
45	      <>
46	        {parts[0]}
47	        <em
48	          style={{
49	            fontStyle: "italic",
50	            color: isDark ? BRAND.rustBright : BRAND.rust,
51	          } as React.CSSProperties}
52	        >
53	          {italicWord}
54	        </em>
55	        {parts[1]}
56	      </>
57	    );
58	  }
59	
60	  return (
61	    <section
62	      style={{
63	        background: isDark ? BRAND.onyx : BRAND.bone,
64	        position: "relative",
65	        overflow: "hidden",
66	        paddingTop: 100,
67	        paddingBottom: 80,
68	      } as React.CSSProperties}
69	    >
70	      {showBlobs && <MangomintBlobs variant={isDark ? "cta" : "hero"} />}
71	
72	      {isDark && (
73	        <>
74	          <div
75	            aria-hidden="true"
76	            style={{
77	              position: "absolute",
78	              top: "20%",
79	              left: "10%",
80	              width: 600,
81	              height: 600,
82	              background: `radial-gradient(circle, rgba(200,53,31,0.20) 0%, transparent 65%)`,
83	              filter: "blur(80px)",
84	              pointerEvents: "none",
85	            } as React.CSSProperties}
86	          />
87	          <div
88	            aria-hidden="true"
89	            style={{
90	              position: "absolute",
91	              bottom: "10%",
92	              right: "10%",
93	              width: 500,
94	              height: 500,
95	              background: `radial-gradient(circle, rgba(200,53,31,0.15) 0%, transparent 65%)`,
96	              filter: "blur(80px)",
97	              pointerEvents: "none",
98	            } as React.CSSProperties}
99	          />
100	        </>
101	      )}
102	
103	      {!isDark && (
104	        <>
105	          <div
106	            aria-hidden="true"
107	            style={{
108	              position: "absolute",
109	              inset: 0,
110	              background: GRADIENT.heroBloom,
111	              pointerEvents: "none",
112	            } as React.CSSProperties}
113	          />
114	          <div
115	            aria-hidden="true"
116	            style={{
117	              position: "absolute",
118	              inset: 0,
119	              opacity: 0.25,
