1	import React from "react";
2	import { Check, Minus } from "lucide-react";
3	import { BRAND, FONT, SHADOW } from "@/lib/brand";
4	
5	type CellValue = boolean | string;
6	
7	interface ComparisonRow {
8	  feature: string;
9	  values: Record<string, CellValue>;
10	}
11	
12	interface Competitor {
13	  key: string;
14	  label: string;
15	  highlighted?: boolean;
16	}
17	
18	interface ComparisonTableProps {
19	  competitors: Competitor[];
20	  rows: ComparisonRow[];
21	  caption?: string;
22	}
23	
24	export function ComparisonTable({
25	  competitors,
26	  rows,
27	  caption,
28	}: ComparisonTableProps) {
29	  const colCount = competitors.length + 1;
30	
31	  return (
32	    <div
33	      style={{
34	        background: BRAND.white,
35	        borderRadius: 18,
36	        boxShadow: SHADOW.card,
37	        overflow: "hidden",
38	      } as React.CSSProperties}
39	    >
40	      {/* Top gradient strip */}
41	      <div
42	        aria-hidden="true"
43	        style={{
44	          height: 4,
45	          background: `linear-gradient(90deg, ${BRAND.amber} 0%, ${BRAND.rust} 50%, ${BRAND.sage} 100%)`,
46	        } as React.CSSProperties}
47	      />
48	
49	      {/* Header row */}
50	      <div
51	        style={{
52	          display: "grid",
53	          gridTemplateColumns: `repeat(${colCount}, 1fr)`,
54	          padding: "14px 24px",
55	          borderBottom: `1px solid ${BRAND.border}`,
56	          background: BRAND.boneDeep,
57	        } as React.CSSProperties}
58	      >
59	        <div
60	          style={{
61	            fontFamily: FONT.sans,
62	            fontSize: 11,
63	            fontWeight: 600,
64	            color: BRAND.stoneLight,
65	            letterSpacing: "0.06em",
66	            textTransform: "uppercase",
67	          } as React.CSSProperties}
68	        >
69	          Feature
70	        </div>
71	        {competitors.map((c) => (
72	          <div
73	            key={c.key}
74	            style={{
75	              fontFamily: FONT.sans,
76	              fontSize: 11,
77	              fontWeight: 600,
78	              color: c.highlighted ? BRAND.rust : BRAND.stoneLight,
79	              letterSpacing: "0.06em",
80	              textTransform: "uppercase",
81	              background: c.highlighted ? BRAND.rustSoft : "transparent",
82	              padding: c.highlighted ? "2px 8px" : "0",
83	              borderRadius: c.highlighted ? 4 : 0,
84	              display: "inline-flex",
85	              alignItems: "center",
86	              gap: 4,
87	            } as React.CSSProperties}
88	          >
89	            {c.highlighted && "★ "}
90	            {c.label}
91	          </div>
92	        ))}
93	      </div>
94	
95	      {/* Data rows */}
96	      {rows.map((row, rowIdx) => (
97	        <div
98	          key={rowIdx}
99	          style={{
100	            display: "grid",
101	            gridTemplateColumns: `repeat(${colCount}, 1fr)`,
102	            padding: "16px 24px",
103	            borderBottom:
104	              rowIdx < rows.length - 1
105	                ? `1px solid ${BRAND.borderSoft}`
106	                : "none",
107	            alignItems: "center",
108	          } as React.CSSProperties}
109	        >
110	          <div
111	            style={{
112	              fontFamily: FONT.sans,
113	              fontSize: 14,
114	              fontWeight: 600,
115	              color: BRAND.onyx,
116	            } as React.CSSProperties}
117	          >
118	            {row.feature}
119	          </div>
120	          {competitors.map((c) => {
121	            const val = row.values[c.key];
122	            return (
123	              <div
124	                key={c.key}
125	                style={{
126	                  background: c.highlighted ? BRAND.rustWash : "transparent",
127	                  display: "flex",
128	                  alignItems: "center",
129	                  padding: "4px 0",
130	                } as React.CSSProperties}
131	              >
132	                {val === true ? (
133	                  <Check size={14} color={BRAND.sage} strokeWidth={2.4} />
134	                ) : val === false ? (
135	                  <Minus size={14} color={BRAND.stoneLight} strokeWidth={2} />
136	                ) : (
137	                  <span
138	                    style={{
139	                      fontFamily: FONT.sans,
140	                      fontSize: 12,
141	                      fontStyle: "italic",
142	                      color: BRAND.stoneLight,
143	                    } as React.CSSProperties}
144	                  >
145	                    {val}
146	                  </span>
147	                )}
148	              </div>
149	            );
150	          })}
151	        </div>
152	      ))}
153	
154	      {caption && (
155	        <div
156	          style={{
157	            padding: "14px 24px",
158	            fontFamily: FONT.sans,
159	            fontSize: 11,
160	            fontStyle: "italic",
161	            color: BRAND.stoneFaint,
162	            textAlign: "center",
163	          } as React.CSSProperties}
164	        >
165	          {caption}
166	        </div>
167	      )}
168	    </div>
169	  );
170	}
